using System;
using System.Linq;
using System.Collections.Generic;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Input;
using System.Windows.Media;
namespace TasiaCraft { public partial class Editor {
 HashSet<string> selectedClipIds=new HashSet<string>(); string openedGroupId;
 List<Clip> SelectedClips(){
  if(openedGroupId!=null&&!project.Groups.Any(g=>g.Id==openedGroupId))openedGroupId=null;
  if(selected==null){selectedClipIds.Clear();return new List<Clip>();}
  if(!project.Clips.Contains(selected)){selected=null;selectedClipIds.Clear();return new List<Clip>();}
  if(!selectedClipIds.Contains(selected.Id)){selectedClipIds.Clear();foreach(var c in ClipGroups.Expand(project,new[]{selected},openedGroupId))selectedClipIds.Add(c.Id);}
  return project.Clips.Where(c=>selectedClipIds.Contains(c.Id)).ToList();
 }
 void SetSelected(IEnumerable<Clip> clips){var list=clips.ToList();if(list.Count>0)selectedMarkerId=null;selectedClipIds=new HashSet<string>(list.Select(c=>c.Id));selected=list.FirstOrDefault();}
 void SyncSelection(){if(live!=null)live.SetSelections(SelectedClips());}
 void SelectClip(Clip c,bool toggle,bool preserve){var current=SelectedClips();if(c==null)SetSelected(new Clip[0]);else{var unit=ClipGroups.Expand(project,new[]{c},openedGroupId);if(toggle){bool remove=unit.All(x=>current.Contains(x));foreach(var x in unit){if(remove)current.Remove(x);else if(!current.Contains(x))current.Add(x);}SetSelected(current);}else if(!preserve||!current.Contains(c))SetSelected(unit);}SyncSelection();Props();}
 void SelectAllClips(){SetSelected(openedGroupId==null?project.Clips:project.Clips.Where(c=>project.Groups.First(g=>g.Id==openedGroupId).ClipIds.Contains(c.Id)));SyncSelection();Props();DrawTimeline();}
 void GroupSelection(){if(busy)return;var clips=SelectedClips();if(clips.Count<2||clips.Any(TrackLocked)||clips.Any(c=>ClipGroups.ForClip(project,c)!=null)){Info("Select at least two ungrouped clips on unlocked tracks.");return;}Checkpoint();int n=1;while(project.Groups.Any(g=>g.Name=="Group"+n))n++;ClipGroups.Create(project,clips,"Group"+n);Refresh();}
 void UngroupSelection(){if(busy)return;var clips=SelectedClips();if(openedGroupId!=null){Info("Return to Main Timeline to ungroup.");return;}var units=ClipGroups.Expand(project,clips);if(units.Any(TrackLocked)){Info("Track is locked.");return;}if(!units.Any(c=>ClipGroups.ForClip(project,c)!=null))return;Checkpoint();ClipGroups.Ungroup(project,units);SetSelected(units);Refresh();}
 void OpenSelectedGroup(){var clips=SelectedClips();if(clips.Count==0)return;var g=ClipGroups.ForClip(project,clips[0]);if(g==null||clips.Any(c=>!g.ClipIds.Contains(c.Id)))return;openedGroupId=g.Id;SetSelected(new Clip[0]);Refresh();}
 void CloseGroup(){openedGroupId=null;SetSelected(new Clip[0]);Refresh();}
 void DeleteSelection(){if(busy)return;var clips=SelectedClips();if(clips.Count==0)return;if(clips.Any(TrackLocked)){Info("Track is locked.");return;}Checkpoint();project.Clips.RemoveAll(c=>clips.Contains(c));ClipGroups.Prune(project);SetSelected(new Clip[0]);Refresh();}
 void MoveSelectionTimeline(double seconds,int tracks){if(busy)return;try{var clips=SelectedClips();if(clips.Count==0)return;var result=new ClipMoveOperation(project,clips).EvaluateTimeline(seconds,tracks);if(!result.Changes)return;Checkpoint();result.Apply();Refresh();}catch(Exception e){Info(e.Message);}}
 bool MultiProps(){var clips=SelectedClips();if(clips.Count<2)return false;properties.Children.Add(Text(clips.Count+" clips selected",14));var g=ClipGroups.ForClip(project,clips[0]);if(g!=null&&clips.All(c=>g.ClipIds.Contains(c.Id))){properties.Children.Add(Text(g.Name));properties.Children.Add(Btn("Rename Group",RenameSelectedGroup));properties.Children.Add(Btn("Open Group",OpenSelectedGroup));properties.Children.Add(Btn("Ungroup  Ctrl+U",UngroupSelection));}else properties.Children.Add(Btn("Group  Ctrl+G",GroupSelection));properties.Children.Add(Text("Drag to move the selection together. Ctrl/Shift-click toggles clips. Open a group to edit its members.",12,muted));return true;}
 void WireSelectionClip(Border b,Clip c){Point origin=new Point();ClipMoveOperation operation=null;bool changed=false,ripple=false,pendingToggle=false;double start=0,oldIn=0,oldDuration=0;int track=0,trim=0;
  b.MouseLeftButtonDown+=(s,e)=>{if(busy)return;Keyboard.Focus(this);ripple=false;pendingToggle=false;if((Keyboard.Modifiers&(ModifierKeys.Control|ModifierKeys.Shift))==ModifierKeys.Shift){var current=SelectedClips();var basis=current.Contains(c)?current:ClipGroups.Expand(project,new[]{c},openedGroupId);try{operation=new ClipMoveOperation(project,RippleEditing.RippleFollowers(project,basis));}catch(Exception ex){Info(ex.Message);operation=null;}ripple=true;pendingToggle=true;origin=e.GetPosition(timeline);trim=0;start=basis.Min(x=>x.Start);track=basis.Min(x=>x.Track);changed=false;e.Handled=true;b.CaptureMouse();return;}
  bool toggle=(Keyboard.Modifiers&ModifierKeys.Control)!=0;SelectClip(c,toggle,true);e.Handled=true;if(toggle){DrawTimeline();return;}var clips=SelectedClips();try{operation=new ClipMoveOperation(project,clips);}catch(Exception ex){Info(ex.Message);DrawTimeline();return;}origin=e.GetPosition(timeline);trim=clips.Count==1?(e.GetPosition(b).X<7?1:e.GetPosition(b).X>b.Width-7?2:0):0;oldIn=c.In;oldDuration=c.Duration;start=clips.Min(x=>x.Start);track=clips.Min(x=>x.Track);changed=false;b.CaptureMouse();};
  b.MouseMove+=(s,e)=>{b.Cursor=Cursors.SizeAll;if(operation==null||!b.IsMouseCaptured)return;var point=e.GetPosition(timeline);double delta=(point.X-origin.X)/zoom;if(!changed&&Math.Abs(point.X-origin.X)+Math.Abs(point.Y-origin.Y)<2)return;var clips=SelectedClips();if(trim!=0){if(TrackLocked(c))return;var media=project.Media.FirstOrDefault(m=>m.Id==c.MediaId);double maximum=media==null||media.Kind=="image"?86400:media.Duration;if(trim==1){delta=Math.Max(-Math.Min(start,oldIn/c.Speed),Math.Min(oldDuration-.1,delta));if(c.Start==start+delta)return;}else{delta=Math.Max(.1,Math.Min((maximum-oldIn)/c.Speed,oldDuration+delta));if(c.Duration==delta)return;}if(!changed){Checkpoint();changed=true;}if(trim==1){c.Start=start+delta;c.In=oldIn+delta*c.Speed;c.Duration=oldDuration-delta;}else c.Duration=delta;c.FadeIn=Math.Min(c.FadeIn,c.Duration);c.FadeOut=Math.Min(c.FadeOut,c.Duration);Canvas.SetLeft(b,110+c.Start*zoom);b.Width=Math.Max(8,c.Duration*zoom);live.Refresh();return;}delta=SnapClipMove(start,delta,clips);try{var result=operation.EvaluateTimeline(delta,ripple?0:-(int)Math.Round((point.Y-origin.Y)/64));if(result.Changes){if(!changed){Checkpoint();changed=true;}result.Apply();Canvas.SetLeft(b,110+(start+result.Seconds)*zoom);Canvas.SetTop(b,TracksTop+4+(project.TrackCount-1-track-result.Tracks)*LaneHeight);live.Refresh();}}catch(Exception ex){Info(ex.Message);}e.Handled=true;};
  b.MouseLeftButtonUp+=(s,e)=>{if(pendingToggle){pendingToggle=false;bool moved=changed;operation=null;b.ReleaseMouseCapture();if(!moved)SelectClip(c,true,false);else Info("Ripple move: following media on the track moved together");DrawTimeline();Props();live.Refresh();UpdateClock();e.Handled=true;return;}if(operation==null)return;operation=null;b.ReleaseMouseCapture();DrawTimeline();Props();live.Refresh();UpdateClock();e.Handled=true;};
  var menu=new ContextMenu();Action<string,string,Action> add=(name,gesture,action)=>{var item=new MenuItem{Header=name,InputGestureText=gesture};item.Click+=(s,e)=>action();menu.Items.Add(item);};add("Cut","Ctrl+X",Cut);add("Copy","Ctrl+C",Copy);add("Paste","Ctrl+V",Paste);add("Delete","Del",DeleteSelection);add("Ripple Delete","Ctrl+Backspace",RippleDeleteSelection);menu.Items.Add(new Separator());add("Stitch Selected Media","Ctrl+Alt+I",StitchSelection);add("Separate Audio and Video","",SeparateSelection);add("Silence Audio","Shift+S",()=>SilenceSelection(true));add("Restore Audio","Shift+R",()=>SilenceSelection(false));menu.Items.Add(new Separator());add("Group","Ctrl+G",GroupSelection);add("Ungroup","Ctrl+U",UngroupSelection);add("Open group","",OpenSelectedGroup);add("Rename Group","",RenameSelectedGroup);add("Main Timeline","",CloseGroup);var locate=new MenuItem{Header="Select in Media Bin"};locate.Click+=(s,e)=>SelectTimelineInBin();menu.Items.Add(new Separator());menu.Items.Add(locate);b.ContextMenu=menu;b.ContextMenuOpening+=(s,e)=>{SelectClip(c,false,true);SyncSelection();locate.IsEnabled=!busy&&MediaBinOperations.SourceReferences(project,SelectedClips()).Count>0;};
 }
} }
